import{z as o,x as s,o as t,c as d,q as A,j as l,D as r,d as e,s as i,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"多层底部抗反射","description":"","frontmatter":{"title":"多层底部抗反射","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/multilayer-barc.md","filePath":"litho/multilayer-barc.md","lastUpdated":1791413859000}'),C={name:"litho/multilayer-barc.md"};function p(h,a,m,D,c,S){const B=s("Mermaid");return t(),d("div",null,[a[2]||(a[2]=A('<h1 id="多层底部抗反射" tabindex="-1">多层底部抗反射 <a class="header-anchor" href="#多层底部抗反射" aria-label="Permalink to &quot;多层底部抗反射&quot;">​</a></h1><div class="epigraph"><p>单层 BARC 只能在有限的角度和衬底上把 $r$ 赶到零附近；高 NA 的角谱宽、衬底种类多，要用两层以上把导纳匹配做宽。</p><footer>—— 分层减反见 Born &amp; Wolf；光刻 SiARC / 双层 BARC 的工艺读法见 Mack、Levinson</footer></div><p><a href="/litho/tarc">上一课</a>收了顶头。缺口是：单层有机 BARC 靠吸收吃反射，在<strong>宽角、多衬底</strong>上往往留残 \\(r\\)，浸没矢量课已经要求对角谱积分。本课钉多层底部抗反射（无机 SiARC、有机+无机、双 BARC）。形貌台阶上的局域反射留给<a href="/litho/topography-reflection">下一课</a>。不重写主干 BARC 课的侧壁波纹叙事，只补层结构。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单层减反：厚度与 \\(n,k\\) 三个自由度，对一个 \\(\\lambda\\)、一个 \\(\\theta\\)、一个衬底可以近零。光瞳里 \\(\\theta\\) 从 0 到 \\(\\arcsin(\\mathrm{NA}/n)\\)，衬底从介质到金属变，单层零点变成「某个角很好、边缘光线仍亮」。残 \\(r\\) 进驻波与 swing，EPE 随场角和图案取向变——看起来像照明问题。</p><p><span class="marginnote">术语翻译：BARC（底部抗反射涂层）是涂在光刻胶下面的一层「消光垫」，用吸收加干涉让照到衬底的光别反射回胶里。反射压住了，驻波和随胶厚摆动的线宽才会消失。</span></p><p>多层：增加界面，用干涉加吸收在角谱上做宽带匹配。典型产线语言：有机 BARC + 含硅无机层（SiON / SiARC），无机层兼硬掩模，有机层调相位与吸收。双有机层则两套 \\(n,k,d\\)。缺口是承认<strong>底部减反是角谱设计</strong>，不是涂一层「黑胶」。</p><h3 id="硬掩模不是副产品" tabindex="-1">硬掩模不是副产品 <a class="header-anchor" href="#硬掩模不是副产品" aria-label="Permalink to &quot;硬掩模不是副产品&quot;">​</a></h3><p>高 NA、薄胶时，光学 BARC 往往不够当刻蚀掩模。多层里的无机层承担转印，光学厚度仍进 \\(r\\) 的矩阵。改硬掩模厚度等于改减反，不能只按刻蚀选择比选 \\(d\\)。上一课胶厚与 BARC 联立，这里变成胶厚与<strong>两层以上</strong>联立。</p><p><span class="marginnote">SiARC 开口刻蚀多一步，缺陷与偏置进 AEI EPE。光学最优若要求极薄无机层，刻蚀会否决。工作点是光学 \\(|r(\\theta)|\\) 与转印的交。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对目标衬底集合与角谱，优化各层 \\(n,k,d\\)，使加权平均 \\(|r|^2\\) 低于预算，并约束刻蚀厚度。s/p 分开看：浸没密线的 TE 权重高，平均不要用非偏振正入射偷懒。换金属层必须重优化，抄介质层的双 BARC 会在金属上回到大摆动。</p><p>验证：变胶厚的 swing 振幅、变 NA / \\(\\sigma\\) 的残驻波、以及不同衬底垫上的 CD。若只有一种测试垫合格，多层匹配不够宽。</p><p><span class="marginnote">数字实例：胶厚每变约四分之一有效波长（几十纳米），往返反射相位就差半圈，swing 曲线上 CD 随胶厚正弦摆动、摆幅可折成几纳米 EPE。多层把角谱上的 \\(|r|\\) 压低后，这条摆动曲线会被明显拍平——这就是「匹配宽度」能不能过验收的直观判据。</span></p>',14)),(t(),l(n,null,{default:r(()=>[i(B,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20ANG%5B%22%E5%AE%BD%E8%A7%92%E8%B0%B1%22%5D%20--%3E%20SPEC%5B%22%7Cr(%CE%B8%2C%20pol)%7C%20%E9%A2%84%E7%AE%97%22%5D%0A%20%20SUB%5B%22%E5%A4%9A%E7%A7%8D%E8%A1%AC%E5%BA%95%22%5D%20--%3E%20SPEC%0A%20%20ML%5B%22%E5%A4%9A%E5%B1%82%20n%2Ck%2Cd%22%5D%20--%3E%20SPEC%0A%20%20HM%5B%22%E7%A1%AC%E6%8E%A9%E6%A8%A1%E5%8E%9A%E5%BA%A6%22%5D%20--%3E%20ET%5B%22%E5%88%BB%E8%9A%80%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20SPEC%20--%3E%20JOIN%5B%22%E8%81%94%E7%AB%8B%E5%B7%A5%E4%BD%9C%E7%82%B9%22%5D%0A%20%20ET%20--%3E%20JOIN%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h3",{id:"与矢量-tcc-的接口",tabindex:"-1"},[e("与矢量 TCC 的接口 "),E("a",{class:"header-anchor",href:"#与矢量-tcc-的接口","aria-label":'Permalink to "与矢量 TCC 的接口"'},"​")],-1)),a[4]||(a[4]=E("p",null,"薄膜矩阵对每个源点、每个偏振给出胶内沉积权重，进矢量 Abbe / TCC。多层 BARC 改的是这张权重，不改光瞳截止。OPC 换 BARC 栈等于换光学模型，旧 SOCS 核作废——与换照明同级，不是「轨道小事」。",-1)),a[5]||(a[5]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=E("p",null,"每层贡献相移与吸收。吸收把从衬底回来的振幅在往返中吃掉；干涉把残余赶到与下层反射反相。宽带靠层间色散和厚度把零点错开，使角谱上没有共同的亮带。单层高 \\(k\\) 也能吃光，但可能在胶底留下过暗、剖面脚、或开口刻蚀窗口差；多层把「吃光」和「相位」分给不同层。",-1)),(t(),l(n,null,{default:r(()=>[i(B,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E5%85%A5%E5%B0%84%E5%85%89%E8%BF%9B%E8%83%B6%22%5D%20--%3E%20DOWN%5B%22%E7%A9%BF%E8%BF%87%20BARC%20%E5%90%84%E5%B1%82%22%5D%0A%20%20DOWN%20--%3E%20SUB%5B%22%E8%A1%AC%E5%BA%95%E5%8F%8D%E5%B0%84%22%5D%0A%20%20SUB%20--%3E%20UP%5B%22%E5%9B%9E%E7%A8%8B%E8%BF%87%E5%B1%82%22%5D%0A%20%20UP%20--%3E%20ABS%5B%22%E6%97%A0%E6%9C%BA%20%2F%20%E9%AB%98%20k%20%E5%B1%82%E5%90%B8%E6%94%B6%E5%90%83%E6%8C%AF%E5%B9%85%22%5D%0A%20%20UP%20--%3E%20PH%5B%22%E6%9C%89%E6%9C%BA%E5%B1%82%E8%B0%83%E7%9B%B8%E4%BD%8D%22%5D%0A%20%20ABS%20--%3E%20SUM%7B%22%E4%B8%8E%E7%9B%B4%E6%8E%A5%E7%95%8C%E9%9D%A2%E7%9A%84%E5%8F%8D%E5%B0%84%E5%8F%A0%E5%8A%A0%22%7D%0A%20%20PH%20--%3E%20SUM%0A%20%20SUM%20--%20%22%E5%8F%8D%E7%9B%B8%22%20--%3E%20ZERO%5B%22%E6%AE%8B%E4%BD%99%20r%20%E8%BF%91%E9%9B%B6%22%5D%0A%20%20SUM%20--%20%22%E6%9F%90%E8%A7%92%E5%BA%A6%E5%90%8C%E7%9B%B8%22%20--%3E%20RES%5B%22%E6%AE%8B%20r%20%E9%A9%BB%E6%B3%A2%20%2F%20swing%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=A('<p><span class="marginnote">常见误区：以为 BARC 就是「越黑越好」。吸收太猛会在胶底留下过暗的剖面与脚部、恶化开口刻蚀窗口。多层方案的高明处是把「吃光」和「调相位」分给不同层各干各的，而不是把所有活塞进一层「黑胶」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给某节点的层数与纳米厚度。EUV 下「BARC」常变成 underlayer / 硬掩模吸收层，机制在末课。禁止编造国产 BARC 的 \\(n,k\\) 表。也不要把多层 BARC 写成 RET：它不抬 NILS 的光学截止，只把假的 \\(z\\) 调制拿掉，让横向 NILS 接近无衬底计算。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>单层 BARC 对宽角、多衬底自由度不够。</li><li>多层用干涉+吸收做角谱匹配，无机层常兼硬掩模。</li><li>厚度联立胶、光学与刻蚀；换衬底必须重优化。</li><li>换栈 = 换 TCC 权重，OPC 核作废。</li><li>下一课：平面分层在台阶上失效。</li><li>出处：Born &amp; Wolf；Mack；Levinson。</li></ul>',5))])}const P=o(C,[["render",p]]);export{f as __pageData,P as default};
